export const messages=Object.fromEntries(rows.trim().split('\n').map(row=>{const [en,ru,kk]=row.split('|');return [en.trim().replace(/\s+/g,' '),{ru,kk}]}));
let language='en';try{const stored=localStorage.getItem('aitu-language');if(['en','ru','kk'].includes(stored))language=stored}catch{}
export const getLanguage=()=>language;
export function t(text){if(language==='en')return text;const clean=text.trim(), direct=messages[clean.replace(/\s+/g,' ')]?.[language];if(direct)return text.replace(clean,direct);
 const patterns=[
 [/^(\d+) mentors shown$/,(_,n)=>language==='ru'?`Показано наставников: ${n}`:`Көрсетілген тәлімгерлер: ${n}`],
 [/^Version (\d+) · (.+)$/,(_,n,status)=>`${language==='ru'?'Версия':'Нұсқа'} ${n} · ${t(status)}`],
 [/^Version history \((\d+)\)$/,(_,n)=>`${language==='ru'?'История версий':'Нұсқалар тарихы'} (${n})`],
 [/^(\d+) of (\d+)$/,(_,a,b)=>language==='ru'?`${a} из ${b}`:`${b} құжаттың ${a}-і`],
 [/^Linked to (.+)$/,(_,name)=>`${language==='ru'?'Связан с':'Байланыстырылған'}: ${name}`],
 [/^(Request|Plan): (.+)$/,(_,kind,status)=>`${t(kind)}: ${t(status)}`],
 [/^School feedback: (.*)$/,(_,value)=>`${language==='ru'?'Комментарий Школы':'Мектеп түсініктемесі'}: ${value}`],
 [/^Preferred mentor: (.*)$/,(_,value)=>`${t('Preferred mentor')}: ${value}`],
 [/^Development focus: (.*)$/,(_,value)=>`${t('Development focus')}: ${value}`],
 [/^(Matching course found|Below matching threshold) · (.+)$/,(_,label,value)=>`${language==='ru'?(label==='Matching course found'?'Найден подходящий курс':'Ниже порога соответствия'):(label==='Matching course found'?'Сәйкес курс табылды':'Сәйкестік шегінен төмен')} · ${value}`],
 [/^Model score: (.+) · Threshold: (.+)$/,(_,score,threshold)=>`${language==='ru'?'Оценка модели':'Модель бағасы'}: ${score} · ${language==='ru'?'Порог':'Шек'}: ${threshold}`],
 [/^This course is illustratively assigned to (.+)\. The score is not a validated measure of mentor suitability\.$/,(_,name)=>language==='ru'?`Курс условно связан с ${name}. Оценка не является подтверждённой мерой пригодности наставника.`:`Курс ${name} профиліне шартты түрде байланыстырылған. Баға тәлімгер жарамдылығының расталған өлшемі емес.`],
 [/^(.+) \(preferred\)$/,(_,name)=>`${name} (${language==='ru'?'предпочтение':'қалаған тәлімгер'})`],
 [/^\(illustrative\)$/,()=>language==='ru'?'(демонстрация)':'(демонстрация)'],
 [/^(.+) — (School of Computing|School of Engineering)$/,(_,name,school)=>`${name} — ${t(school)}`],
 [/^(.+) · (School of Computing|School of Engineering)$/,(_,name,school)=>`${name} · ${t(school)}`],
 [/^Version (\d+) · (.+) · (\d+) activities$/,(_,n,status,count)=>`${language==='ru'?'Версия':'Нұсқа'} ${n} · ${t(status)} · ${count} ${language==='ru'?'задач':'тапсырма'}`]
 ];for(const [regex,replace] of patterns)if(regex.test(clean))return text.replace(clean,clean.replace(regex,replace));return text;
}
const sources=new WeakMap();
const ignore='[data-no-translate],script,style,textarea,input,[name="skill"],#skill-description,.course-title';
function translateText(node){if(node.parentElement?.closest(ignore))return;const previous=sources.get(node);const source=previous&&node.nodeValue===previous.last?previous.source:node.nodeValue;const translated=t(source);sources.set(node,{source,last:translated});if(node.nodeValue!==translated)node.nodeValue=translated;}
const attributes=new WeakMap();
export function localize(root=document.body){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())translateText(node);for(const el of root.querySelectorAll('[placeholder],[aria-label],[title],[alt]')){if(el.closest('[data-no-translate]'))continue;let record=attributes.get(el)||{};for(const name of ['placeholder','aria-label','title','alt']){if(!el.hasAttribute(name))continue;const value=el.getAttribute(name),prior=record[name],source=prior&&value===prior.last?prior.source:value,last=t(source);record[name]={source,last};if(last!==value)el.setAttribute(name,last)}attributes.set(el,record)}document.documentElement.lang=language;for(const el of document.querySelectorAll('[data-language]')){el.setAttribute('aria-pressed',String(el.dataset.language===language));el.classList.toggle('active',el.dataset.language===language)}}
export function setLanguage(next){if(!['en','ru','kk'].includes(next))return;language=next;try{localStorage.setItem('aitu-language',next)}catch{}localize();document.dispatchEvent(new Event('languagechange'))}
export function languageSwitcher(){return `<div class="language-switcher" role="group" aria-label="Language / Язык / Тіл">${[['en','EN','English'],['kk','KZ','Қазақша'],['ru','RU','Русский']].map(([code,label,title])=>`<button type="button" data-language="${code}" lang="${code}" title="${title}" aria-pressed="${language===code}" class="${language===code?'active':''}">${label}</button>`).join('')}</div>`}
export function startLocalization(){localize();new MutationObserver(records=>{const roots=new Set();for(const r of records){if(r.type==='characterData')translateText(r.target);else for(const added of r.addedNodes){if(added.nodeType===Node.TEXT_NODE)translateText(added);else if(added.nodeType===Node.ELEMENT_NODE)roots.add(added)}}for(const root of roots)localize(root)}).observe(document.body,{childList:true,subtree:true,characterData:true});document.addEventListener('click',e=>{const button=e.target.closest('[data-language]');if(button)setLanguage(button.dataset.language)})}
